#!/usr/bin/env python3
import csv, json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
src = root / 'output' / 'rewrite-master-enriched.csv'
dst = root / 'output' / 'cvr-apartments-dashboard.html'
with src.open(newline='', encoding='utf-8') as f:
    rows = list(csv.DictReader(f))
data = json.dumps(rows, ensure_ascii=False).replace('</', '<\\/')
html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CVR Property Intake</title><style>
:root{--ink:#17343A;--deep:#0E252A;--soft:#315C63;--mist:#DCE7E5;--brass:#9A7B4F;--paper:#F7F6F1;--line:#d6dfdc;--text:#536264;--red:#a44b3e;--ok:#4b765e}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--text);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{max-width:1480px;margin:auto;padding:30px 34px 60px}.mast{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid var(--line);padding-bottom:24px}.eyebrow{font:11px monospace;letter-spacing:.14em;text-transform:uppercase;color:var(--brass)}h1{margin:10px 0 8px;color:var(--ink);font-size:clamp(30px,4vw,56px);line-height:1;letter-spacing:-.06em}.lede{max-width:700px;color:var(--soft)}.stamp{font:11px monospace;color:var(--soft);text-align:right}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:22px 0}.stat{background:#fff;border:1px solid var(--line);padding:16px;min-height:88px}.stat b{display:block;color:var(--ink);font-size:28px}.stat span,.meta{font:11px monospace;letter-spacing:.05em;text-transform:uppercase;color:var(--soft)}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0 12px}.controls input,.controls select{border:1px solid var(--line);background:#fff;padding:11px 13px;color:var(--ink);min-width:180px}.controls input{flex:1;min-width:260px}.table-wrap{overflow:auto;border:1px solid var(--line);background:#fff}table{border-collapse:collapse;width:100%;min-width:1100px}th{background:var(--deep);color:#fff;text-align:left;padding:13px 12px;font:11px monospace;text-transform:uppercase;letter-spacing:.08em}td{border-bottom:1px solid #e5ebe8;padding:14px 12px;vertical-align:top}tr:hover td{background:#f8faf7}.title{font-weight:800;color:var(--ink);max-width:350px}.pill{display:inline-block;border-radius:99px;padding:4px 8px;font:10px monospace;text-transform:uppercase}.ready{background:#e2efe7;color:var(--ok)}.lookup{background:#eee5d6;color:#765b35}.blocked{background:#f6e3df;color:var(--red)}.price{font-weight:800;color:#765b35;white-space:nowrap}.foot{display:flex;justify-content:space-between;margin-top:14px;font-size:12px;color:var(--soft)}@media(max-width:850px){.shell{padding:20px 16px}.mast{display:block}.stamp{text-align:left;margin-top:18px}.stats{grid-template-columns:repeat(2,1fr)}.stats .stat:last-child{grid-column:span 2}}
</style></head><body><main class="shell"><header class="mast"><div><div class="eyebrow">Source intake / internal review</div><h1>Property intake, before WordPress.</h1><p class="lede">A live-source QA board for the Da Nang rental set. Review evidence, mapping and blockers before any import.</p></div><div class="stamp">MASTER / ENRICHED<br>NO WP CHANGES</div></header><section class="stats" id="stats"></section><section class="controls"><input id="q" type="search" placeholder="Search title, building, source key…"><select id="s"><option value="">All statuses</option></select><select id="t"><option value="">All types</option></select><select id="c"><option value="">All cities</option></select></section><div class="table-wrap"><table><thead><tr><th>Listing</th><th>Building / project</th><th>Type · city</th><th>Facts</th><th>Price</th><th>QA status</th></tr></thead><tbody id="body"></tbody></table></div><footer class="foot"><span id="count"></span><span>No WordPress or Media Library changes made.</span></footer></main><script>const D=__DATA__,E=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c])),L=s=>String(s||'').replaceAll('_',' '),C=s=>s.includes('invalid')||s.includes('source_review')?'blocked':s==='ready_for_review'?'ready':s==='needs_lookup'?'lookup':'review';function opts(id,k){[...new Set(D.map(r=>r[k]).filter(Boolean))].sort().forEach(v=>document.querySelector(id).insertAdjacentHTML('beforeend',`<option>${E(v)}</option>`))}function render(){let q=document.querySelector('#q').value.toLowerCase(),s=document.querySelector('#s').value,t=document.querySelector('#t').value,c=document.querySelector('#c').value,o=D.filter(r=>(!s||r.content_status===s)&&(!t||r.property_type===t)&&(!c||r.property_city===c)&&(r.original_title+' '+r.rewritten_title+' '+r.building_name+' '+r.source_key).toLowerCase().includes(q));document.querySelector('#body').innerHTML=o.map(r=>`<tr><td><div class="title">${E(r.rewritten_title||r.original_title)}</div><div class="meta">${E(r.source_key)} · ${E(r.source_http_status||'—')}</div></td><td><b>${E(r.building_name||'Unresolved')}</b><div class="meta">${E(r.project_confidence||'unknown')} · ${E(r.building_slug||'—')}</div></td><td>${E(r.property_type||'—')}<div class="meta">${E(r.property_city||'—')}</div></td><td>${E(r.bedrooms||'—')} bd · ${E(r.bathrooms||'—')} ba<br><span class="meta">${E(r.size||'—')} sqm · ${E(r.property_features||'No features')}</span></td><td><span class="price">${E(r.public_price||'—')} ${E(r.price_currency||'')}</span><div class="meta">source ${E(r.source_price||'—')} · −${E(r.discount_percent||'8')}%</div></td><td><span class="pill ${C(r.content_status)}">${E(L(r.content_status))}</span><div class="meta">${E((r.qa_notes||'').slice(0,110))}</div></td></tr>`).join('');document.querySelector('#count').textContent=`Showing ${o.length} of ${D.length} listings`}let n=D.reduce((a,r)=>(a[r.content_status]=(a[r.content_status]||0)+1,a),{});document.querySelector('#stats').innerHTML=[['Total listings',D.length],['Ready for review',n.ready_for_review||0],['Needs mapping',n.needs_lookup||0],['Blocked',(n.invalid_size_review_required||0)+(n.needs_source_review||0)],['Source HTTP 200',D.filter(r=>r.source_http_status==='200').length]].map(x=>`<div class="stat"><b>${x[1]}</b><span>${x[0]}</span></div>`).join('');opts('#s','content_status');opts('#t','property_type');opts('#c','property_city');render();['q','s','t','c'].forEach(id=>document.querySelector('#'+id).addEventListener('input',render))</script></body></html>'''
dst.write_text(html.replace('__DATA__', data), encoding='utf-8')
print(f'Wrote {dst} with {len(rows)} listings')
